ST.xhtml:p:
RTring_GearIn(CLK := g_bAvoidAxisGearInM  OR bGearIn);
RTring_GearOut(CLK := g_bAvoidAxisGearOutM OR bGearOut);

IF RTring_GearIn.Q THEN
  bGearIn := FALSE;
  g_bAvoidAxisGearInM := FALSE;
  IF AntiRejection6.NCTOPLC.AXISSTATE <> 8 THEN
    nGearstate := 1;
    g_dAvoidAxisNodeYPosGearInState := g_diYMachineCoordinate;
  ELSE
    M.ENABLE[318] := 0;
  END_IF;
END_IF;
IF RTring_GearOut.Q THEN
  bGearOut := FALSE;
  g_bAvoidAxisGearOutM := FALSE;
  IF AntiRejection6.NCTOPLC.AXISSTATE = 8 THEN
    nGearstate := 2;
  ELSE
    M.ENABLE[318] := 0;
  END_IF;
END_IF;
CASE nGearstate OF
  0:
  nGearstate := 0;
  1:
  g_AntiRejection6GearIn.EXECUTE := TRUE;
  g_AntiRejection6GearIn.RatioNumerator := 1.0;
  g_AntiRejection6GearIn.RatioDenominator := 1;
  IF g_AntiRejection6GearIn.InGear THEN
    nGearstate := 0;
    M.ENABLE[318] := 0;
  END_IF;
  IF g_AntiRejection6GearIn.ERROR OR g_AntiRejection6GearIn.COMMANDABORTED THEN
    g_AntiRejection6GearIn.Execute := FALSE;
    nGearstate := 0;
  END_IF;
  2:
  g_AntiRejection6GearOut.EXECUTE := TRUE;
  g_AntiRejection6GearIn.EXECUTE := FALSE;
  IF g_AntiRejection6GearOut.DONE THEN
    g_AntiRejection6GearOut.EXECUTE := FALSE;
    M.ENABLE[318] := 0;
    nGearstate := 0;
  END_IF;
  IF g_AntiRejection6GearOut.ERROR THEN
    g_AntiRejection6GearOut.EXECUTE := FALSE;
       nGearstate := 3;
  END_IF;
  3:
  g_AntiRejection6Stop.EXECUTE := TRUE;
  IF g_AntiRejection6Stop.DONE THEN
    g_AntiRejection6Stop.EXECUTE := FALSE;
    nGearstate := 0;
    M.ENABLE[318] := 0;
  END_IF;
  IF g_AntiRejection6Stop.COMMANDABORTED OR g_AntiRejection6Stop.ERROR THEN
    g_AntiRejection6Stop.EXECUTE := FALSE;
    nGearstate := 0;
    M.ENABLE[318] := 0;
  END_IF;
END_CASE;
